selector_to_html = {"a[href=\"../autoapi/pyskyfire/ducts/pipe/Pipe.html#pyskyfire.ducts.pipe.Pipe.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_swirl</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'fluids'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">bend_length_scale</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'hydraulic'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/ducts/pipe/DuctResult.html#pyskyfire.ducts.pipe.DuctResult\" title=\"pyskyfire.ducts.pipe.DuctResult\"><span class=\"pre\">DuctResult</span></a></span></span></dt><dd><p>March irreversible pressure losses from inlet to outlet.</p><p><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Straight</span></code> and <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> connections charge wall\nfriction on the hydraulic diameter, the latter times the curvature\nmultiplier, along the helix a swirling flow follows, plus the loss of\nany change of area (<a class=\"reference internal\" href=\"#pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\" title=\"pyskyfire.ducts.pipe.Pipe.area_change_loss_coefficient\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">area_change_loss_coefficient</span></code></a>). A\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code> charges its complete loss coefficient. Every loss\nis on the through-flow head <code class=\"docutils literal notranslate\"><span class=\"pre\">rho*c_m**2/2</span></code>. Acceleration and heat\ntransfer are intentionally absent: a change of area alters the\nvelocities, and so the static pressure, but adds no reversible term\nto the marched stagnation pressure.</p></dd>", "a[href=\"#geometry-and-output\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Geometry and output<a class=\"headerlink\" href=\"#geometry-and-output\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Scene.add()</span></code> builds a component and returns its root <code class=\"docutils literal notranslate\"><span class=\"pre\">SceneNode</span></code>. Nodes hold\nlocal transforms, children, anchors, optional meshes, and scalar fields. Their\npath IDs distinguish circuits, channels, hubs, shrouds, and blades, which is\nhow the viewer\u2019s selections and groups refer to them. Sibling names must be unique. A scene\ncan contain several instances of the same component, including overlapping\ncomponents at the origin. No fluid-network connectivity is checked.</p><p>The scene uses renderer-independent NumPy meshes. Desktop output uses PyVista;\nstandalone HTML uses bundled Three.js and TrackballControls with no network assets\nor Python server. HTML carries geometry, hierarchy, transforms, and original\nfield values directly, rather than converting a VTK rendering window to glTF.\nThe HTML viewer supports unconstrained trackball rotation, pan (right-drag, or\nCtrl+drag on a trackpad), zoom, and an <code class=\"docutils literal notranslate\"><span class=\"pre\">R</span></code> key that restores the initial view.\nParts take one default colour unless a component has a reason to set its own,\nsuch as the red of an inlet or outlet opening; <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_colors</span></code> on the chamber\nand heat exchanger and <code class=\"docutils literal notranslate\"><span class=\"pre\">colors</span></code> on the turbine paint parts apart when wanted.</p>", "a[href=\"../autoapi/pyskyfire/viz/components/ImpellerComponent.html#pyskyfire.viz.components.ImpellerComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.components.ImpellerComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.components.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerComponent</span></span></dt><dd><p>Display prepared impeller.geometry arrays, with the existing local x shaft axis.</p><p>Optional <code class=\"docutils literal notranslate\"><span class=\"pre\">results</span></code> maps part names (hub, shroud, blade_N) to dictionaries\nof mesh-aligned FieldData. <code class=\"docutils literal notranslate\"><span class=\"pre\">inlet</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">shaft</span></code> are axial centre datums;\nthere is no discrete outlet port on a radially discharging impeller.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/components/ThrustChamberComponent.html#pyskyfire.viz.components.ThrustChamberComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.components.ThrustChamberComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.components.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ThrustChamberComponent</span></span></dt><dd><p>Cooling-channel surfaces with optional RegenResult fields.</p><p>Each layout seed is constructed once. Instances share its immutable mesh\nand fields and carry separate rotations and identities. No hot wall is\nconstructed. <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_N.inlet/outlet</span></code> anchors refer to the first seed\u2019s\nfirst channel, at its end-section polygon centre, not a manifold port.\nEvery channel also exposes its own inlet/outlet anchors.</p><p>A circuit with a result records its coolant\u2019s CoolProp name as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">metadata[\"fluid\"]</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_colors</span></code> paints each circuit apart;\nwithout it every channel takes the default colour.</p></dd>", "a[href=\"#cooling-fields\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Cooling fields<a class=\"headerlink\" href=\"#cooling-fields\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">cooling_data</span></code> accepts one <code class=\"docutils literal notranslate\"><span class=\"pre\">RegenResult</span></code>, an iterable, or a mapping whose values\nare results. Mapping keys have no geometric meaning. Results match by\n<code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_index</span></code>, with <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_name</span></code> checked as an additional safeguard.\nDuplicate indices, invalid indices, and mismatched names raise errors. These\nchecks cannot prove that a result came from the identical geometry revision;\nthe caller must supply results belonging to the supplied chamber.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Scene(color_by=None)</span></code> retains component colors while keeping attached data.\nSet <code class=\"docutils literal notranslate\"><span class=\"pre\">scene.color_by</span> <span class=\"pre\">=</span> <span class=\"pre\">\"p_static\"</span></code> before display or export to select a field.\nSupported cooling fields are:</p>", "a[href=\"#placement-and-anchors\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Placement and anchors<a class=\"headerlink\" href=\"#placement-and-anchors\" title=\"Link to this heading\">\u00b6</a></h2><p>All component geometry keeps its documented local coordinates. The common frame\nis right-handed Cartesian <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">y,</span> <span class=\"pre\">z)</span></code>; the existing chamber and impeller axes\nare local x. Neither component is automatically recentered. Positive rotations\nfollow the right-hand rule.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">position=(x,y,z)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">rotation=(rx,ry,rz)</span></code> use translation in metres and\nextrinsic xyz Euler angles in radians. A <code class=\"docutils literal notranslate\"><span class=\"pre\">scipy.spatial.transform.Rotation</span></code> is\nalso accepted. Alternatively supply <code class=\"docutils literal notranslate\"><span class=\"pre\">transform=psf.viz.Transform(...)</span></code>, or\nconstruct one with <code class=\"docutils literal notranslate\"><span class=\"pre\">Transform(matrix=rigid_4x4_matrix)</span></code>. Scaling and reflection\nare rejected. Explicit transform and position/rotation cannot be combined.</p>", "a[href=\"#heat-exchangers-inside-chambers\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Heat exchangers inside chambers<a class=\"headerlink\" href=\"#heat-exchangers-inside-chambers\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">HeatExchangerComponent(exchanger,</span> <span class=\"pre\">results)</span></code> sweeps the exchanger\u2019s sections\nusing its transported frames. Pass a <code class=\"docutils literal notranslate\"><span class=\"pre\">ChamberInstallation</span></code> as the first\nargument to retain the simulated chamber-relative placement. It supports the\nsame <code class=\"docutils literal notranslate\"><span class=\"pre\">Scene.add</span></code> transforms, parent hierarchy and inlet/outlet anchors as other\ncomponents. See <a class=\"reference internal\" href=\"heat-exchangers.html#put-an-exchanger-and-chamber-in-the-same-scene\"><span class=\"std std-ref\">the combined baffle scene example</span></a>.</p>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.add\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.add\">\n<span class=\"sig-name descname\"><span class=\"pre\">add</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">component</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transform</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">position</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">parent</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">anchor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">attach_to</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tags</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/ducts/pipe/Pipe.html#pyskyfire.ducts.pipe.Pipe\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.Pipe\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Pipe</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">connections</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">core_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_diameter_change</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.02</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A circular duct swept along a path, with an optional core, and its loss solver.</p><p>The section normal to the path is a circular bore of <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code>, with a\nconcentric core of <code class=\"docutils literal notranslate\"><span class=\"pre\">core_diameter</span></code> inside it where that is not zero. A\nplain pipe has no core. A core may run the whole length, as in coaxial\nlines, or only part of it: it may start from a point, as a turbine\u2019s nose\ndoes, and end, bluntly or tapering.</p><p>The march evaluates each connection at one section, the mean of its two\nends. Where the section varies, the pipe therefore splits\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Straight</span></code> and <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> connections itself until its\narea and hydraulic diameter each change by at most\n<code class=\"docutils literal notranslate\"><span class=\"pre\">max_diameter_change</span></code> (relative, the area as the diameter of the circle\nof the same area) across each piece, placing the extra stations where the\nsection changes fastest. A constant section is left exactly as supplied,\nand so is every <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code>. <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">path</span></code>, <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">stations</span></code> and\nevery result refer to the resolved stations, which include all of the\nsupplied ones.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.data_url\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.data_url\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">data_url</span></span></dt><dd><p>Interactive HTML for Report.add_iframe().</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/components/PipeComponent.html#pyskyfire.viz.components.PipeComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.components.PipeComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.components.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PipeComponent</span></span></dt><dd><p>Display an explicitly defined pipe; never route or modify a solver model.</p><p>The pipe supplies its own geometry. A <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code> offers\n<code class=\"docutils literal notranslate\"><span class=\"pre\">display_path(segments=...)</span></code>, which opens its rounded and continuous bend\nconnections into arcs for drawing without touching the solved model;\n<code class=\"docutils literal notranslate\"><span class=\"pre\">segments</span></code> sets the drawn sides per quarter turn. Any other object is read through <code class=\"docutils literal notranslate\"><span class=\"pre\">centerline</span></code>, an (N,3)\nCartesian polyline in metres, and <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code>, a positive scalar or one\nradius per station, and is drawn exactly as supplied. The local frame is\nthe frame of those coordinates (no implicit recentering).</p><p>A pipe with a core is drawn as a <code class=\"docutils literal notranslate\"><span class=\"pre\">\"core\"</span></code> surface, one per stretch the\ncore runs along, inside a translucent <code class=\"docutils literal notranslate\"><span class=\"pre\">\"bore\"</span></code> of <code class=\"docutils literal notranslate\"><span class=\"pre\">opacity</span></code>, both\nchildren of the returned node, which carries the bore\u2019s end anchors.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">results</span></code> is a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">DuctResult</span></code>, or a mapping of\nfield names to FieldData: point-associated with one value per station, or\ncell-associated with one value per connection. Station values are\ninterpolated along refined bends and repeated around each ring; connection\nvalues fill the rings spanning that connection. Every surface carries the\nsame fields.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/pipe/DuctResult.html#pyskyfire.ducts.pipe.DuctResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.DuctResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DuctResult</span></span></dt><dd><p>Station states and per-interval diagnostics from a duct loss march.</p><p><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Pipe.solve()</span></code> and <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code> both\nreturn one. <code class=\"docutils literal notranslate\"><span class=\"pre\">p_stagnation</span></code> is the marched pressure: the inlet pressure\nless the irreversible losses up to each station. It includes the swirl\u2019s\ndynamic head. The march is adiabatic, so <code class=\"docutils literal notranslate\"><span class=\"pre\">T_stagnation</span></code> is the inlet\ntemperature at every station, and <code class=\"docutils literal notranslate\"><span class=\"pre\">states</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">density</span></code> are evaluated\nat the two.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">meridional_velocity</span></code> is the through-flow velocity <code class=\"docutils literal notranslate\"><span class=\"pre\">c_m</span></code> normal to the\nflow area, <code class=\"docutils literal notranslate\"><span class=\"pre\">swirl_velocity</span></code> the circumferential <code class=\"docutils literal notranslate\"><span class=\"pre\">c_u</span></code> at the mean\nradius, and <code class=\"docutils literal notranslate\"><span class=\"pre\">velocity</span></code> their magnitude, which without swirl is the\nthrough-flow velocity. <code class=\"docutils literal notranslate\"><span class=\"pre\">T_static</span></code> is the stagnation temperature less\n<code class=\"docutils literal notranslate\"><span class=\"pre\">velocity**2/(2*cp)</span></code>, with <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> taken at the same state as the\ndensity. Like <code class=\"docutils literal notranslate\"><span class=\"pre\">p_static</span></code> it is a first-order correction, not a\nstatic-state solution.</p><p>Per-interval arrays have one value fewer than the stations.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">loss_coefficient</span></code> is referred to the through-flow head\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rho*c_m**2/2</span></code> on the interval\u2019s mean section. <code class=\"docutils literal notranslate\"><span class=\"pre\">darcy_factor</span></code> is the\nfactor applied, including any curvature multiplier, and NaN over a lumped\nbend.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">stations</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">connections</span></code> are a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code>\u2019s resolved path, and\nNone for an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnularDuct</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is the\nCoolProp name the transport carried, or None when it named none.</p></dd>", "a[href=\"#assemble-a-3d-scene\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Assemble a 3D scene<a class=\"headerlink\" href=\"#assemble-a-3d-scene\" title=\"Link to this heading\">\u00b6</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Scene</span></code> combines component geometry and simulation fields in a common coordinate\nsystem. Use metres, radians, pascals, kelvin, and other base SI units. There are\nno unit-conversion arguments. Scene geometry illustrates the simulated model;\nCAD export remains a separate workflow.</p>", "a[href=\"../autoapi/pyskyfire/index.html#module-pyskyfire\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire<a class=\"headerlink\" href=\"#module-pyskyfire\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire - A Python library for rocket engine simulation and design.</p>", "a[href=\"#migration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Migration<a class=\"headerlink\" href=\"#migration\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">make_engine_3d()</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">Engine3DViewer</span></code> emit <code class=\"docutils literal notranslate\"><span class=\"pre\">DeprecationWarning</span></code>. The old factory\ndelegates to the scene implementation and retains its viewer handle for existing\ncallers. Its <code class=\"docutils literal notranslate\"><span class=\"pre\">show</span></code> parameter now actually controls opening the desktop window.\nReplace factory calls with <code class=\"docutils literal notranslate\"><span class=\"pre\">Scene()</span></code> plus <code class=\"docutils literal notranslate\"><span class=\"pre\">scene.add(ThrustChamberComponent(...))</span></code>.\nMove <code class=\"docutils literal notranslate\"><span class=\"pre\">stride</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_arc_pts</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">layout</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_colors</span></code> onto the component;\nkeep <code class=\"docutils literal notranslate\"><span class=\"pre\">save_html()</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">data_url</span></code> on the scene and remove <code class=\"docutils literal notranslate\"><span class=\"pre\">close()</span></code> calls on it.</p>", "a[href=\"#selection-and-groups\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Selection and groups<a class=\"headerlink\" href=\"#selection-and-groups\" title=\"Link to this heading\">\u00b6</a></h2><p>Shift+click adds a component to the selection, or removes it again, and the\nbox then lists every selected part. Selected parts are tinted a calm blue,\nmixed in so a field\u2019s colours still show through. Right-click lists every part under the\ncursor, front to back: each component the cursor meets, its circuits and other\nnamed parts, and the channel or blade actually under the cursor (repeated\nchannels, blades and vanes elsewhere are left out). Hovering an entry tints\nthe part lightly, clicking selects it, and Shift+click adds it. This is\nhow a circuit inside a chamber, or a pipe behind a volute, is reached.</p><p>Any selection can be saved as a named group from the box. The groups panel\nlists those alongside groups the scene brings with it:</p>", "a[href=\"heat-exchangers.html#put-an-exchanger-and-chamber-in-the-same-scene\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Put an exchanger and chamber in the same scene<a class=\"headerlink\" href=\"#put-an-exchanger-and-chamber-in-the-same-scene\" title=\"Link to this heading\">\u00b6</a></h2><p>Passing a <code class=\"docutils literal notranslate\"><span class=\"pre\">ChamberInstallation</span></code> uses its simulation transform automatically.\nA raw <code class=\"docutils literal notranslate\"><span class=\"pre\">HeatExchanger</span></code> instead uses assembly coordinates and supports ordinary\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Scene.add(position=...,</span> <span class=\"pre\">rotation=...)</span></code> placement. If the chamber itself has a\nscene transform, add the installed exchanger with <code class=\"docutils literal notranslate\"><span class=\"pre\">parent=chamber_node</span></code> so\nboth move together. Explicit scene placement overrides the installation\u2019s root\ntransform, and affects the drawing only.</p><p>Each channel is drawn as its wetted passage, the surface the coolant touches,\nnot the outer envelope of its walls. The adapter exposes fluid temperature,\nstatic pressure, velocity, enthalpy, and <code class=\"docutils literal notranslate\"><span class=\"pre\">T_coolant_wall</span></code>, the wall\ntemperature at the wetted interface, in the field selector. <code class=\"docutils literal notranslate\"><span class=\"pre\">T_coolant_wall</span></code>\nuses contact-area averages on each exposed surface segment; inactive surfaces\nstay uncoloured. The opposite interface is not drawn; it remains in\n<code class=\"docutils literal notranslate\"><span class=\"pre\">result.walls</span></code>. Each copied channel has inlet/outlet anchors; root\n<code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_N.inlet/outlet</span></code> anchors refer to the first copy.</p>", "a[href=\"#pipes-and-ducts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pipes and ducts<a class=\"headerlink\" href=\"#pipes-and-ducts\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">PipeComponent</span></code> draws a <code class=\"docutils literal notranslate\"><span class=\"pre\">ducts.Pipe</span></code> directly; the solved model is never routed\nor modified.</p>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.show\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.show\">\n<span class=\"sig-name descname\"><span class=\"pre\">show</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Scene</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'Pyskyfire</span> <span class=\"pre\">3D'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">color_by</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">clim</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_axes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Assemble components for desktop or standalone HTML display.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">anchor</span></code> names the added component\u2019s local anchor; <code class=\"docutils literal notranslate\"><span class=\"pre\">attach_to</span></code> is a\nworld-space Anchor. Attachment mates their outward x axes in opposition.\nIt is a one-time placement calculation, with no fluid-network constraints.\nExplicit placement and anchor placement are mutually exclusive.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tags</span></code> labels the added node, a string or an iterable of them. Nodes\nsharing a tag appear together as one group in the HTML viewer, so a\ngrouping written into the script survives regenerating the results.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">show_axes</span></code> adds a corner orientation triad marking the scene axes\n(x red, y green, z blue). It is an orientation cue only, not a measuring\ngrid: it carries no ticks and does not indicate the origin or scale.</p></dd>", "a[href=\"#extension-components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Extension components<a class=\"headerlink\" href=\"#extension-components\" title=\"Link to this heading\">\u00b6</a></h2><p>Custom components implement <code class=\"docutils literal notranslate\"><span class=\"pre\">build()</span> <span class=\"pre\">-&gt;</span> <span class=\"pre\">SceneNode</span></code>, returning a fresh hierarchy.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">MeshData(points,</span> <span class=\"pre\">triangles)</span></code> stores local vertices and triangle connectivity.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">FieldData(values,</span> <span class=\"pre\">units,</span> <span class=\"pre\">label,</span> <span class=\"pre\">association=\"point\")</span></code> attaches immutable scalar\narrays; <code class=\"docutils literal notranslate\"><span class=\"pre\">association=\"cell\"</span></code> means one value per triangle. Units are descriptive\nSI metadata, never conversion inputs. Same-named fields must describe the same\nphysical quantity across components. Impeller <code class=\"docutils literal notranslate\"><span class=\"pre\">results</span></code> accepts mappings from\npart names (<code class=\"docutils literal notranslate\"><span class=\"pre\">hub</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">shroud</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">blade_N</span></code>) to dictionaries of mesh-aligned fields.</p>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.save_html\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.save_html\">\n<span class=\"sig-name descname\"><span class=\"pre\">save_html</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
